const fs = require('node:fs')
const path = require('node:path')
const { IOSConfig, withDangerousMod, withXcodeProject } = require('expo/config-plugins')

// Why: the Action Button, Shortcuts and Siri run App Intents, and iOS only finds App Intents (and their App
// Shortcuts) compiled into the app target itself, not in a pod. So the intent is written into the app target here;
// modules/orca-xeno-talk hands each press to JS. Opening the app keeps the microphone usable for a new call.
const FILE = 'XenoTalkIntent.swift'

const SWIFT = `import AppIntents
import Foundation

// Generated by plugins/ios-xeno-talk-intent.js.
@available(iOS 16.0, *)
struct TalkToXenoIntent: AppIntent {
  static let title: LocalizedStringResource = "Talk to Xeno"
  static let description = IntentDescription("Start talking to Xeno; run it again to send.")
  static let openAppWhenRun = true

  @MainActor
  func perform() async throws -> some IntentResult {
    // Left for JS to take if it isn't listening yet, as when the press launched the app.
    UserDefaults.standard.set(true, forKey: "orca.xenoTalkPending")
    NotificationCenter.default.post(name: Notification.Name("OrcaXenoTalkRequested"), object: nil)
    return .result()
  }
}

@available(iOS 16.0, *)
struct XenoAppShortcuts: AppShortcutsProvider {
  static var appShortcuts: [AppShortcut] {
    AppShortcut(
      intent: TalkToXenoIntent(),
      phrases: ["Talk to \\(.applicationName)"],
      shortTitle: "Talk to Xeno",
      systemImageName: "waveform"
    )
  }
}
`

module.exports = function withIosXenoTalkIntent(config) {
  config = withDangerousMod(config, [
    'ios',
    (cfg) => {
      const { platformProjectRoot, projectName } = cfg.modRequest
      fs.writeFileSync(path.join(platformProjectRoot, projectName, FILE), SWIFT)
      return cfg
    }
  ])
  return withXcodeProject(config, (cfg) => {
    const filepath = `${cfg.modRequest.projectName}/${FILE}`
    if (!cfg.modResults.hasFile(filepath)) {
      IOSConfig.XcodeUtils.addBuildSourceFileToGroup({
        filepath,
        groupName: cfg.modRequest.projectName,
        project: cfg.modResults
      })
    }
    return cfg
  })
}

module.exports.XENO_TALK_INTENT_SWIFT = SWIFT
